//code generated by human fixed by copilot
package fixer;

import filehandling.FileHandlings;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
// Co-authored with Claude and Co-pilot
public class JunkFileCleaner {
    private static final String MAC_FOLDER = "__MACOSX"; // edge case
    private static final String MAC_FILE = ".DS_Store";
    private static final String CLASS_EXTENSION = ".class";
    private static final String JAVA_EXTENSION = ".java";
    private static final String INNER_CLASS_SEPARATOR = "$";
    private static final int NOT_FOUND = -1;

    // Removes files that are not part of the submission:
    // - __MACOSX folders and .DS_Store files that macOS adds to zips
    // - old .class files of the student's own code,
    // e.g. Q1a.class next to Q1a.java.
    // Class files given with the exam (e.g. Circle.class, which has
    // no Circle.java) are kept.
    public static void clean(File folder, ArrayList<String> messages) {
        ArrayList<Exception> problems = new ArrayList<>();
        junkCleaner(folder, messages, problems);
        addProblemMessages(messages, problems);
    }

    public static void junkCleaner(File folder, ArrayList<String> messages,
            ArrayList<Exception> problems) {
        File[] items = folder.listFiles();

        if (items == null) {
            if (folder.isDirectory()) {
                problems.add(new IOException("Cannot inspect folder "
                        + folder + "."));
            }
            return;
        }

        for (File item : items) {
            String name = item.getName();

            if (item.isDirectory()) {
                if (name.equals(MAC_FOLDER)) {
                    FileHandlings.deleteFolder(item);
                    if (item.exists()) {
                        problems.add(new IOException("Cannot remove "
                                + MAC_FOLDER + " folder."));
                    } else {
                        messages.add("Removed " + MAC_FOLDER + " folder.");
                    }
                } else {
                    junkCleaner(item, messages, problems);
                }
            } else if (name.equals(MAC_FILE)) {
                if (item.delete()) {
                    messages.add("Removed " + MAC_FILE + " from "
                            + folder.getName() + ".");
                } else {
                    problems.add(new IOException("Cannot remove " + item
                            + "."));
                }
            } else if (name.endsWith(CLASS_EXTENSION)
                    && hasJavaFile(folder, name)) {
                if (item.delete()) {
                    messages.add("Removed old compiled file " + name
                            + " from " + folder.getName() + ".");
                } else {
                    problems.add(new IOException("Cannot remove " + item
                            + "."));
                }
            }
        }
    }

    private static void addProblemMessages(ArrayList<String> messages,
            ArrayList<Exception> problems) {
        for (Exception problem : problems) {
            messages.add(problem.getMessage());
        }
    }

    // Checks if the .java file that this .class file was compiled from
    // is in the same folder.
    // e.g. Q1a.class -> Q1a.java, and inner classes like
    // Q2a$Helper.class -> Q2a.java
    private static boolean hasJavaFile(File folder, String classFileName) {
        int nameLength = classFileName.length() - CLASS_EXTENSION.length();
        String className = classFileName.substring(0, nameLength);

        int separatorPosition = className.indexOf(INNER_CLASS_SEPARATOR);
        if (separatorPosition != NOT_FOUND) {
            className = className.substring(0, separatorPosition);
        }

        return new File(folder, className + JAVA_EXTENSION).isFile();
    }

    public static void folderCompare(File folder, File modelFolder,
            ArrayList<String> messages, ArrayList<Exception> problems) {

        if (!folder.isDirectory() || !modelFolder.isDirectory()) {
            problems.add(new IOException(
                    "Target folder or model folder is invalid."));
            return;
        }

        File[] items = folder.listFiles();

        if (items == null) {
            problems.add(new IOException(
                    "Cannot inspect folder " + folder + "."));
            return;
        }

        for (File item : items) {
            File modelItem = new File(modelFolder, item.getName());

            if (item.isDirectory()) {
                if (modelItem.isDirectory()) {
                    folderCompare(item, modelItem, messages, problems);
                } else {
                    FileHandlings.deleteFolder(item);

                    if (!item.exists()) {
                        messages.add("Removed unnecessary folder "
                                + item.getName() + ".");
                    } else {
                        problems.add(new IOException(
                                "Cannot remove folder " + item + "."));
                    }
                }
            } else if (!modelItem.isFile()) {
                if (item.delete()) {
                    messages.add("Removed unnecessary file "
                            + item.getName() + ".");
                } else {
                    problems.add(new IOException(
                            "Cannot remove file " + item + "."));
                }
            }
        }

    }

    public static void extraFileCleaner(File folder, File modelFolder,
            ArrayList<String> messages) {

        ArrayList<Exception> problems = new ArrayList<>();

        folderCompare(folder, modelFolder, messages, problems);

        addProblemMessages(messages, problems);
    }
}
